-- 540: Original BrillaPrep WASSCE Core Mathematics sprint 3 beta questions, part 2 of 10 (batch wassce-core-math-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_540_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_540_guard;
INSERT INTO _migration_540_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_006' AND NOT (q.topic_id IS 'topic_wassce_p2_math_alg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Given that x + 2y = 8 and x − y = 2, find the value of x + y.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 4","B. 6","C. 2","D. 10"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Subtract the second equation from the first: (x + 2y) − (x − y) = 8 − 2, so 3y = 6 and y = 2. Then x = 2 + y = 4, and x + y = 4 + 2 = 6. (4 and 2 are the individual values of x and y.) Therefore the correct answer is B: 6.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_006' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_540_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_007' AND NOT (q.topic_id IS 'topic_wassce_p2_math_alg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Make t the subject of the formula s = ½(u + v)t.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. t = s(u + v)/2","B. t = 2s(u + v)","C. t = 2s/(u + v)","D. t = (u + v)/(2s)"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Multiply both sides by 2 to clear the fraction: 2s = (u + v)t. Then divide both sides by (u + v): t = 2s/(u + v). (t = 2s(u + v) multiplies instead of dividing by (u + v).) Therefore the correct answer is C: t = 2s/(u + v).' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Rearrange' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_007' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_540_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_008' AND NOT (q.topic_id IS 'topic_wassce_p2_math_alg' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Simplify (3x²)² × 2x.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 18x⁴","B. 6x⁵","C. 9x⁵","D. 18x⁵"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Square the bracket first: (3x²)² = 9x⁴. Then multiply by 2x: 9x⁴ × 2x = 18x⁵, since x⁴ × x = x⁵. (6x⁵ wrongly doubles 3 instead of squaring it; 18x⁴ forgets to add the powers of x.) Therefore the correct answer is D: 18x⁵.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Simplify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_008' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_540_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_009' AND NOT (q.topic_id IS 'topic_wassce_p2_math_geo' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Two angles lie on a straight line. One of them is 65°. Find the other angle.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 115°","B. 25°","C. 65°","D. 90°"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Angles on a straight line sum to 180°, so the other angle is 180° − 65° = 115°. (25° is the complement 90° − 65°, confusing straight-line with right-angle pairs.) Therefore the correct answer is A: 115°.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_009' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_540_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wcms3_010' AND NOT (q.topic_id IS 'topic_wassce_p2_math_geo' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Two angles of a triangle are 50° and 60°. Find the third angle.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 110°","B. 70°","C. 30°","D. 120°"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The angles of a triangle sum to 180°: 50° + 60° = 110°, so the third angle is 180° − 110° = 70°. (110° is the sum of the two given angles, not the third angle.) Therefore the correct answer is B: 70°.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wcms3_010' AND NOT (r.batch_id IS 'wassce-core-math-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_006', 'topic_wassce_p2_math_alg', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Given that x + 2y = 8 and x − y = 2, find the value of x + y.', 'multiple_choice', NULL, '["A. 4","B. 6","C. 2","D. 10"]', 'B', 'Subtract the second equation from the first: (x + 2y) − (x − y) = 8 − 2, so 3y = 6 and y = 2. Then x = 2 + y = 4, and x + y = 4 + 2 = 6. (4 and 2 are the individual values of x and y.) Therefore the correct answer is B: 6.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_007', 'topic_wassce_p2_math_alg', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Make t the subject of the formula s = ½(u + v)t.', 'multiple_choice', NULL, '["A. t = s(u + v)/2","B. t = 2s(u + v)","C. t = 2s/(u + v)","D. t = (u + v)/(2s)"]', 'C', 'Multiply both sides by 2 to clear the fraction: 2s = (u + v)t. Then divide both sides by (u + v): t = 2s/(u + v). (t = 2s(u + v) multiplies instead of dividing by (u + v).) Therefore the correct answer is C: t = 2s/(u + v).', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Rearrange', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_008', 'topic_wassce_p2_math_alg', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Simplify (3x²)² × 2x.', 'multiple_choice', NULL, '["A. 18x⁴","B. 6x⁵","C. 9x⁵","D. 18x⁵"]', 'D', 'Square the bracket first: (3x²)² = 9x⁴. Then multiply by 2x: 9x⁴ × 2x = 18x⁵, since x⁴ × x = x⁵. (6x⁵ wrongly doubles 3 instead of squaring it; 18x⁴ forgets to add the powers of x.) Therefore the correct answer is D: 18x⁵.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Simplify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_009', 'topic_wassce_p2_math_geo', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Two angles lie on a straight line. One of them is 65°. Find the other angle.', 'multiple_choice', NULL, '["A. 115°","B. 25°","C. 65°","D. 90°"]', 'A', 'Angles on a straight line sum to 180°, so the other angle is 180° − 65° = 115°. (25° is the complement 90° − 65°, confusing straight-line with right-angle pairs.) Therefore the correct answer is A: 115°.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wcms3_010', 'topic_wassce_p2_math_geo', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Two angles of a triangle are 50° and 60°. Find the third angle.', 'multiple_choice', NULL, '["A. 110°","B. 70°","C. 30°","D. 120°"]', 'B', 'The angles of a triangle sum to 180°: 50° + 60° = 110°, so the third angle is 180° − 110° = 70°. (110° is the sum of the two given angles, not the third angle.) Therefore the correct answer is B: 70°.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO1', NULL, NULL, 'board_waec');
